.psPageHeader.sapMVBox {
  position: relative;
  overflow: hidden;
  min-height: 100px;
  padding: 1.5rem 2rem;
  border-bottom: 1px solid #ede8e0;
  justify-content: center;
  background: url("../images/header.png") right center / cover no-repeat;
}
.psPageHeaderContent.sapMVBox {
  position: relative;
