  gap: 0.2rem !important;
}
.psPageHeaderTitle.sapMTitle {
  font-size: 1.375rem !important;
  font-weight: 700 !important;
  color: #1d2d3e !important;
  letter-spacing: -0.01em !important;
  line-height: 1.3 !important;
}
