   ════════════════════════════════════════════════════════════ */
.asTable.sapMTable {
  margin: 0 !important;
}

.asTable .sapMText {
  font-size: 0.82rem !important;
}
.asTable .sapMListTblCell {
  padding: 0.2rem 0.5rem !important;
}
.asTable .sapMListTblHeaderCell {
  background: #f5f6f7 !important;
  font-size: 0.78rem !important;
  font-weight: 600 !important;
  color: #32363a !important;
  border-bottom: 2px solid #0070d2 !important;
  padding: 0.3rem 0.5rem !important;
}
.asTable .sapMListTblRow:hover .sapMListTblCell {
  background: #f0f6ff !important;
}

/* ── 연도별 추이 ── */
.asTrendYear.sapMText {
  font-weight: 700 !important;
  color: #32363a !important;
}
.asDeltaBadge.sapMObjStatusStateSuccess .sapMObjStatusText {
  color: #107e3e !important;
  font-size: 0.8rem !important;
}
.asDeltaBadge.sapMObjStatusStateError .sapMObjStatusText {
  color: #bb0000 !important;
  font-size: 0.8rem !important;
}
.asDeltaBadge.sapMObjStatusStateWarning .sapMObjStatusText {
  color: #e76500 !important;
  font-size: 0.8rem !important;
}
.asDeltaBadge.sapMObjStatusStateNone .sapMObjStatusText {
  color: #8d9cb0 !important;
  font-size: 0.8rem !important;
}

/* ════════════════════════════════════════════════════════════
   알림 배너
   ════════════════════════════════════════════════════════════ */
.asAlertStrip.sapMMessageStrip {
  margin: 0 !important;
