}
.asKpiIcon--red.sapUiIcon {
  color: #bb0000 !important;
}
.asKpiValue--warning.sapMText {
  color: #e76500 !important;
  font-weight: 700 !important;
}

/* ════════════════════════════════════════════════════════════
