              cancel:  function (oEvent) { oEvent.getSource().getBinding("items").filter([]); },
              search:  function (oEvent) {
                var sVal = oEvent.getParameter("value");
                var aF   = sVal ? [new Filter("Partner", FilterOperator.Contains, sVal)] : [];
