/* ── 공통 다크 네이비 그라디언트 ─────────────────────────────── */
.qmNavyGrad {
    background: linear-gradient(135deg, #003d87 0%, #0a5fc8 100%);
    border-radius: 10px;
    box-shadow: 0 4px 18px rgba(0, 61, 135, 0.32);
    position: relative;
    overflow: hidden;
}
/* 장식 원 */
.qmNavyGrad::before {
    content: '';
    position: absolute;
    top: -28px; right: -28px;
    width: 100px; height: 100px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.07);
    pointer-events: none;
}
.qmNavyGrad::after {
    content: '';
    position: absolute;
    bottom: -20px; left: -20px;
    width: 70px; height: 70px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    pointer-events: none;
}

